or):\\n    def __init__(self, code: str):\\n        self.code = code\\n        super().__init__(code)\\n\\n\\ndef _deny(suffix: str):\\n    raise CreatorLifecycleReadonlyError('CREATOR_LIFECYCLE_READ_' + suffix)\\n\\n\\nclass CreatorLifecycleReadonlyReader:\\n    def __init__(self, *, connect_factory=None):\\n        self._connect = connect_factory or connect_read_only\\n\\n    @staticmethod\\n    def _rows(conn, scope, cutoff, kind, decision_id=None):\\n        table, identity, _, _ = _SPECS[kind]\\n        extra_column = 'decision_id,' if kind == 'lane' else ''\\n        extra_filter = ' AND decision_id=%s' if kind == 'lane' else ''\\n        direction = ' DESC' if kind == 'start' else ''\\n        limit = 1 if kind == 'start' else MAX_ROWS + 1\\n        sql = (\\n            f'SELECT org_id,project_id,{identity} AS entity_id,revision,content_hash,created_at,'\\n            f'{extra_column}octet_length(authority_data::text) AS authority_bytes,'\\n            f'CASE WHEN octet_length(authority_data::text)<={MAX_ITEM_BYTES} '\\n            'THEN authority_data ELSE NULL END AS authority_data '\\n            f'FROM {table} WHERE org_id=%s AND project_id=%s AND created_at<=%s'\\n            f'{extra_filter} ORDER BY created_at{direction},revision{direction},{identity}{direction} LIMIT %s'\\n        )\\n        params = (*scope.key, cutoff)\\n        if kind == 'lane':\\n            params = (*params, decision_id)\\n        rows = conn.execute(sql, (*params, limit)).fetchall()\\n        if len(rows) > MAX_ROWS or kind == 'start' and len(rows) > 1:\\n            _deny('LIMIT_EXCEEDED')\\n        return rows\\n\\n    @staticmethod\\n    def _decode(row, kind, scope, cutoff, total):\\n        _, _, model, timestamp = _SPECS[kind]\\n        size = row['authority_bytes']\\n        if type(size) is not int or size < 1:\\n            _deny('AUTHORITY_DRIFT')\\n        if size > MAX_ITEM_BYTES or total + size > MAX_TOTAL_BYTES:\\n            _deny('LIMIT_EXCEEDED')\\n        value = model.model_validate(row['authority_data'])\\n        # Delivery observations are append-only v1; their DTO has no revision.\\n        revision = 1 if kind == 'delivery' else value.revision\\n        if ((row['org_id'], row['project_id']) != scope.key\\n                or (value.tenant.org_id, value.tenant.project_id) != scope.key\\n                or value.content_hash != row['content_hash']\\n                or type(row['revision']) is not int or revision != row['revision']):\\n            _deny('AUTHORITY_DRIFT')\\n        identity = {\\n            'start': 'decision_id', 'lane': 'observation_id',\\n            'contract': 'collaboration_id', 'delivery': 'observation_id',\\n            'relationship': 'relationship_id',\\n        }[kind]\\n        created = row['created_at']\\n        observed = getattr(value, timestamp)\\n        if (getattr(value, identity) != row['entity_id']\\n                or not isinstance(created, datetime) or created.utcoffset() is None\\n                or observed.utcoffset() is None or observed != created or created > cutoff):\\n            _deny('AUTHORITY_DRIFT')\\n        return value, total + size\\n\\n    def read(self, scope: TenantScope) -> CreatorLifecycleView:\\n        try:\\n            with self._connect(scope) as conn:\\n                if (conn.read_only is not True or conn.autocommit is not False\\n                        or conn.isolation_level != IsolationLevel.REPEATABLE_READ):\\n                    _deny('CONNECTION_INVALID')\\n                cutoff = conn.execute('SELECT transaction_timestamp() AS cutoff').fetchone()['cutoff']\\n                if not isinstance(cutoff, datetime) or cutoff.utcoffset() is None:\\n                    _deny('AUTHORITY_DRIFT')\\n                total = 0\\n                values: dict[str, list[Any]] = {}\\n                for kind in _SPECS:\\n                    start = values.get('start', [])\\n                    rows = ([] if kind == 'lane' and not start else\\n                            self._rows(conn, scope, cutoff, kind,\\n                                       start[0].decision_id if kind == 'lane' else None))\\n                    values[kind] = []\\n                    for row in rows:\\n                        value, total = self._decode(row, kind, scope, cutoff, total)\\n                        if kind == 'lane':\\n                            current = start[0]\\n                            ref = value.start_decision_ref\\n                            if (row['decision_id'] != current.decision_id\\n                                    or ref.resource_type != 'CreatorBatchStartDecisionRevision'\\n                                    or ref.resource_id != current.decision_id\\n                                    or ref.revision != current.revision\\n                                    or ref.content_hash != current.content_hash\\n                                    or value.lane_id not in {lane.lane_id for lane in current.lanes}):\\n                                _deny('AUTHORITY_DRIFT')\\n                        values[kind].append(value)\\n                start = values['start'][0] if values['start'] else None\\n                lanes = list(start.lanes) if start else []\\n                latest = {observation.lane_id: observation for observation in values['lane']}\\n                if start:\\n                    lanes = [lane.model_copy(update={\\n                        'outcome': latest[lane.lane_id].outcome,\\n                        'resolved_outcome': latest[lane.lane_id].resolved_outcome,\\n                        'action_receipt_ref': latest[lane.lane_id].action_receipt_ref,\\n                    }) if lane.lane_id in latest else lane for lane in lanes]\\n                    start = start.model_copy(update={\\n                        'lanes': lanes, 'ledger': _ledger(lanes, start.ledger.eligible_items),\\n                    })\\n                result = CreatorLifecycleView(\\n                    tenant=dict(orgId=scope.org_id, projectId=scope.project_id),\\n                    evaluatedAt=cutoff, latestStart=start,\\n                    ledger=_ledger(lanes, start.ledger.eligible_items if start else 0),\\n                    contracts=values['contract'], deliveries=values['delivery'],\\n                    relationships=values['relationship'],\\n                    blockers=list(start.operational_blockers) if start else ['CREATOR_BATCH_START_NOT_AVAILABLE'],\\n                    allowedCommands=[], externalEffectsAllowed=False,\\n                )\\n                if len(result.model_dump_json(by_alias=True).encode('utf-8')) > MAX_TOTAL_BYTES:\\n                    _deny('LIMIT_EXCEEDED')\\n                return result\\n        except CreatorLifecycleReadonlyError:\\n            raise\\n        except psycopg.Error:\\n            _deny('UNAVAILABLE')\\n        except (ValueError, KeyError, TypeError, AttributeError):\\n            _deny('AUTHORITY_DRIFT')\\n\\nFILE services/aos-api/tests/aip/test_creator_lifecycle_readonly.py SHA 84b7eefe943649b83b1e22ea9e1c8b7ac0e5ea0693a40f40c705e78dd3d8e91d\\n\\\"\\\"\\\"Dedicated read-only snapshot tests; fixture rows are not human approvals.\\\"\\\"\\\"\\nimport copy\\nimport json\\nfrom contextlib import contextmanager\\nfrom datetime import timedelta\\n\\nimport psycopg\\nimport pytest\\nfrom psycopg import IsolationLevel\\n\\nfrom aos_api.ecommerce_workshop_creator_lifecycle import CreatorActionLaneBinding\\nfrom aos_api.ecommerce_workshop_creator_lifecycle_readonly import (\\n    CreatorLifecycleReadonlyReader, CreatorLifecycleReadonlyError,\\n    MAX_ROWS, MAX_ITEM_BYTES, MAX_TOTAL_BYTES,\\n)\\nfrom test_creator_lifecycle_read_tenant import SCOPE, NOW, HASH, item, ref\\n\\nTABLES = {\\n    'start': 'ecommerce_creator_batch_start_decision_revision',\\n    'lane': 'ecommerce_creator_lane_observation',\\n    'contract': 'ecommerce_creator_contract_revision',\\n    'delivery': 'ecommerce_creator_delivery_observation',\\n    'relationship': 'ecommerce_creator_relationship_revision',\\n}\\nMETHODS = {\\n    'start': 'latest_start_for_tenant_or_none', 'lane': 'list_lane_observations',\\n    'contract': 'list_contracts', 'delivery': 'list_deliveries', 'relationship': 'list_relationships',\\n}\\n\\n\\ndef row(kind, value=None):\\n    value = value or item(METHODS[kind])\\n    data = value.model_dump(mode='json', by_alias=True)\\n    identities = {'start': 'decisionId', 'lane': 'observationId', 'contract': 'collaborationId',\\n                  'delivery': 'observationId', 'relationship': 'relationshipId'}\\n    result = dict(org_id=SCOPE.org_id, project_id=SCOPE.project_id,\\n                  entity_id=data[identities[kind]], revision=data.get('revision', 1),\\n                  content_hash=data['contentHash'], created_at=NOW,\\n                  authority_bytes=len(json.dumps(data).encode()), authority_data=data)\\n    if kind == 'lane':\\n        result['decision_id'] = data['startDecisionRef']['resourceId']\\n    return result\\n\\n\\ndef snapshot(rows=None, *, fail=None, readonly=True, isolation=IsolationLevel.REPEATABLE_READ, cutoff=NOW):\\n    rows = rows or {}\\n    calls, connections = [], []\\n    class Result:\\n        def __init__(self, values): self.values = values\\n        def fetchone(self): return self.values[0] if self.values else None\\n        def fetchall(self): return self.values\\n    class Connection:\\n        read_only = readonly\\n        isolation_level = isolation\\n        autocommit = False\\n        def execute(self, sql, params=()):\\n            assert sql.startswith('SELECT ')\\n            calls.append((sql, params))\\n            if 'transaction_timestamp()' in sql:\\n                return Result([dict(cutoff=cutoff)])\\n            assert tuple(params[:2]) == SCOPE.key\\n            assert cutoff in params\\n            kind = next(k for k, table in TABLES.items() if f'FROM {table} ' in sql)\\n            assert 'LIMIT %s' in sql\\n            assert params[-1] == (1 if kind == 'start' else MAX_ROWS + 1)\\n            assert 'created_at<=%s' in sql\\n            assert 'observed_at' not in sql\\n            assert 'CASE WHEN octet_length' in sql\\n            if fail == kind: raise psycopg.OperationalError('fixture unavailable')\\n            return Result(rows.get(kind, []))\\n        def commit(self): pytest.fail('reader must not commit a mutation')\\n    @contextmanager\\n    def connect(scope):\\n        assert scope == SCOPE\\n        connections.append(scope)\\n        yield Connection()\\n    return CreatorLifecycleReadonlyReader(connect_factory=connect), calls, connections\\n\\n\\ndef started_rows():\\n    start = item(METHODS['start'])\\n    lane = CreatorActionLaneBinding(\\n        candidateRef=ref('CreatorCandidateRevision'), actionKind='outreach-message',\\n        actionTypeRef={**ref('ActionTypeRevision'), 'resourceId': 'ecommerce.creator.outreach-message'},\\n        impactPreviewRef=ref('ImpactPreviewRevision'), adapterCapabilityRef=ref('AdapterCapabilityRevision'),\\n        accountBindingRef=ref('AccountBindingRevision'), budgetReservationRef=ref('ActionBudgetReservationRevision'),\\n        approvalPolicyRef=ref('ApprovalPolicyRevision'), laneId='fixture-lane', bindingHash=HASH)\\n    start = start.model_copy(update={'lanes': [lane], 'ledger': start.ledger.model_copy(update={\\n        'eligible_items': 1, 'lanes': 1, 'prepared': 1})})\\n    observation = item(METHODS['lane']).model_copy(update={\\n        'start_decision_ref': type(lane.candidate_ref)(**dict(\\n            resourceType='CreatorBatchStartDecisionRevision', resourceId=start.decision_id,\\n            revision=start.revision, contentHash=start.content_hash))})\\n    return dict(start=[row('start', start)], lane=[row('lane', observation)])\\n\\n\\ndef test_empty_is_complete_single_readonly_snapshot_with_database_cutoff():\\n    reader, calls, connections = snapshot()\\n    view = reader.read(SCOPE)\\n    assert len(connections) == 1 and len(calls) == 5\\n    assert view.evaluated_at == NOW and view.latest_start is None\\n    assert view.contracts == view.deliveries == view.relationships == []\\n    assert view.ledger.lanes == 0 and view.allowed_commands == []\\n    assert view.external_effects_allowed is False\\n    assert view.blockers == ['CREATOR_BATCH_START_NOT_AVAILABLE']\\n\\n\\ndef test_complete_typed_view_and_lane_projection_without_producer_calls():\\n    rows = started_rows()\\n    rows.update({k: [row(k)] for k in ['contract', 'delivery', 'relationship']})\\n    reader, calls, connections = snapshot(rows)\\n    view = reader.read(SCOPE)\\n    assert len(connections) == 1 and len(calls) == 6\\n    assert view.latest_start.lanes[0].lane_id == 'fixture-lane'\\n    assert view.ledger.lanes == view.ledger.prepared == 1\\n    assert len(view.contracts) == len(view.deliveries) == len(view.relationships) == 1\\n    assert view.allowed_commands == [] and view.external_effects_allowed is False\\n\\n\\n@pytest.mark.parametrize('field,value', [\\n    ('org_id', 'dev-org'), ('project_id', 'other'), ('entity_id', 'wrong'),\\n    ('revision', 9), ('content_hash', 'b' * 64), ('created_at', NOW + timedelta(seconds=1)),\\n])\\ndef test_outer_row_integrity_drift_is_rejected(field, value):\\n    bad = row('contract'); bad[field] = value\\n    reader, _, _ = snapshot(dict(contract=[bad]))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\n\\n@pytest.mark.parametrize('field,value', [('orgId', 'dev-org'), ('projectId', 'other')])\\ndef test_inner_json_tenant_drift_is_rejected(field, value):\\n    bad = row('contract'); bad['authority_data']['tenant'][field] = value\\n    reader, _, _ = snapshot(dict(contract=[bad]))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\n\\n@pytest.mark.parametrize('readonly,isolation', [(False, IsolationLevel.REPEATABLE_READ),\\n                                               (True, IsolationLevel.READ_COMMITTED)])\\ndef test_non_readonly_or_non_repeatable_connection_is_denied(readonly, isolation):\\n    reader, calls, _ = snapshot(readonly=readonly, isolation=isolation)\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='CONNECTION_INVALID'):\\n        reader.read(SCOPE)\\n    assert calls == []\\n\\n\\ndef test_database_failure_is_unavailable_not_empty_success():\\n    reader, _, _ = snapshot(fail='contract')\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='UNAVAILABLE'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_clock_without_timezone_is_denied():\\n    reader, _, _ = snapshot(cutoff=NOW.replace(tzinfo=None))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_row_limit_sentinel_rejects_instead_of_truncating():\\n    reader, _, _ = snapshot(dict(contract=[row('contract')] * (MAX_ROWS + 1)))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='LIMIT_EXCEEDED'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_exact_row_limit_can_be_read_when_total_bytes_fit():\\n    reader, _, _ = snapshot(dict(contract=[row('contract')] * MAX_ROWS))\\n    assert len(reader.read(SCOPE).contracts) == MAX_ROWS\\n\\n\\ndef test_sql_suppressed_large_json_is_rejected_before_parse():\\n    bad = row('contract'); bad.update(authority_bytes=MAX_ITEM_BYTES + 1, authority_data=None)\\n    reader, _, _ = snapshot(dict(contract=[bad]))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='LIMIT_EXCEEDED'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_total_byte_limit_is_not_treated_as_partial_or_empty():\\n    rows = [row('contract') for _ in range(MAX_TOTAL_BYTES // MAX_ITEM_BYTES + 1)]\\n    for value in rows: value['authority_bytes'] = MAX_ITEM_BYTES\\n    reader, _, _ = snapshot(dict(contract=rows))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='LIMIT_EXCEEDED'):\\n        reader.read(SCOPE)\\n\\n\\n@pytest.mark.parametrize('mutation', ['decision', 'hash', 'lane'])\\ndef test_lane_exact_lineage_drift_is_rejected(mutation):\\n    rows = copy.deepcopy(started_rows()); bad = rows['lane'][0]\\n    if mutation == 'decision': bad['decision_id'] = 'other'\\n    if mutation == 'hash': bad['authority_data']['startDecisionRef']['contentHash'] = 'b' * 64\\n    if mutation == 'lane': bad['authority_data']['laneId'] = 'other'\\n    reader, _, _ = snapshot(rows)\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_bad_json_shape_fails_closed():\\n    bad = row('contract'); bad['authority_data'] = {'tenant': {'orgId': 'org-org'}}\\n    reader, _, _ = snapshot(dict(contract=[bad]))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\n\\ndef test_delivery_observation_without_dto_revision_requires_stored_v1():\\n    bad = row('delivery'); bad['revision'] = 2\\n    reader, _, _ = snapshot(dict(delivery=[bad]))\\n    with pytest.raises(CreatorLifecycleReadonlyError, match='AUTHORITY_DRIFT'):\\n        reader.read(SCOPE)\\n\\nFILE .evidence/qyh-creator-lifecycle-bounded-reader-20261014/native_snapshot.py SHA 0759aaa03cbeba25179d1cddf4dc690e6d7a1e2364926092383fe70e9a7d6bd3\\n\\\"\\\"\\\"One owned tmpfs PG fixture: no original volume, users, tokens or data.\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport contextlib, datetime, hashlib, json, secrets, subprocess, sys, time\\n\\nimport psycopg\\nfrom psycopg import IsolationLevel, sql\\nfrom psycopg.rows import dict_row\\n\\nR = Path(__file__).resolve().parents[2]\\nE = Path(__file__).resolve().parent\\nsys.path.insert(0, str(R / 'services/aos-api'))\\nsys.path.insert(0, str(R / 'services/aos-api/tests/aip'))\\nfrom aos_api.ecommerce_workshop_creator_lifecycle_readonly import CreatorLifecycleReadonlyReader, CreatorLifecycleReadonlyError\\nfrom aos_api.tenant_scope import TenantScope\\nfrom test_creator_lifecycle_read_tenant import item\\n\\nNAME = 'qyh-creator-lifecycle-bounded-native-20261014-r1'\\nOWNER = 'codex-01a13484-f019-7d82-94ce-812396db9124'\\nIMAGE = 'sha256:7e7dbab8d3b431a20793a6d99cb5a6bc84e44914309917f1bf5589a7568cdefd'\\nSCOPE = TenantScope('org-org', 'dev-project')\\nTABLES = (\\n    ('ecommerce_creator_batch_start_decision_revision', 'decision_id', 'batch_id TEXT', 'latest_start_for_tenant_or_none'),\\n    ('ecommerce_creator_lane_observation', 'observation_id', 'decision_id TEXT,lane_id TEXT', 'list_lane_observations'),\\n    ('ecommerce_creator_contract_revision', 'collaboration_id', '', 'list_contracts'),\\n    ('ecommerce_creator_delivery_observation', 'observation_id', '', 'list_deliveries'),\\n    ('ecommerce_creator_relationship_revision', 'relationship_id', '', 'list_relationships'),\\n)\\n\\ndef docker(*args):\\n    return subprocess.run(['docker', '--context', 'colima-aos-extension', *args], capture_output=True, text=True)\\n\\ndef save(name, value):\\n    with (E / name).open('x') as f:\\n        json.dump(value, f, indent=2); f.write('\\\\n'); f.flush()\\n\\nassert not (E / 'native-r1-intent.json').exists(), 'existing fixture: readonly reconcile, no replay'\\nlease = json.loads((R.parent / 'docs/palantier/AOS项目开发上下文/memory/receipts/tasks' / (E.name + '.json')).read_text())\\nassert lease['owner'] == OWNER and datetime.datetime.fromisoformat(lease['lease_expires_at']) > datetime.datetime.now(datetime.timezone.utc)\\nassert not docker('inspect', NAME).returncode == 0, 'existing named fixture: reconcile'\\nport_probe = subprocess.run(['lsof', '-t', '-iTCP:18571', '-sTCP:LISTEN'], capture_output=True, text=True)\\nassert not port_probe.stdout.strip(), 'fixture port already owned'\\npassword = secrets.token_hex(24)\\nsave('native-r1-intent.json', dict(name=NAME, owner=OWNER, port=18571, tmpfs=True, originalVolumeTouched=False))\\ncreated = docker('run', '-d', '--name', NAME, '--label', 'aos.task=' + E.name, '--label', 'aos.owner=' + OWNE